namespace AlphaPlus.Settings.Site.Features.QRCodeMemberSignIn.Helpers
{
    using System;
    using System.Drawing;
    using System.Drawing.Imaging;
    using System.IO;
    using Gma.QrCodeNet.Encoding;
    using Gma.QrCodeNet.Encoding.Windows.Render;
    using ONEbook.Common.Auth;

    public interface QrCodeAdapter
    {
        string Generate(string url);
        
        string CreateMobileLoginUrl(bool isLocalTest, string domain, int siteid, string username, int tokenExpireSecond);
    }

    public class QrCodeAdapterImpl : QrCodeAdapter
    {
        private readonly string qrcodeLocalLinkTest = "http://ha.nexdev.net:7407/site-main/";

        public string Generate(string url) // TODO
        {
            var encoder = new QrEncoder(ErrorCorrectionLevel.M);
            QrCode qrCode;
            encoder.TryEncode(url, out qrCode);

            var graphiscRenderer = new GraphicsRenderer(
                new FixedModuleSize(4, QuietZoneModules.Four));

            var memoryStream = new MemoryStream();
            graphiscRenderer.WriteToStream(qrCode.Matrix, null, memoryStream);

            return $"data:image/jpeg;base64,{Convert.ToBase64String(memoryStream.ToArray())}";
        }

        public string CreateMobileLoginUrl(
            bool isLocalTest,
            string domain, 
            int siteid, 
            string username, 
            int tokenExpireSecond)
       => isLocalTest ? 
            qrcodeLocalLinkTest : 
            Authentication.Instance.CreateMobileLoginUrl(domain, siteid, username, tokenExpireSecond);
    }
}